/**
 * @suppress
 */
public object FfiConverterTypeErpEngine: FfiConverter<ErpEngine, Pointer> {

    override fun lower(value: ErpEngine): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): ErpEngine {
        return ErpEngine(value)
    }

    override fun read(buf: ByteBuffer): ErpEngine {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: ErpEngine) = 8UL

    override fun write(value: ErpEngine, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



