sealed class ErpFfiException: kotlin.Exception() {
    
    class DatabaseException(
        
        val `details`: kotlin.String
        ) : ErpFfiException() {
        override val message
            get() = "details=${ `details` }"
    }
    
    class ModuleException(
        
        val `details`: kotlin.String
        ) : ErpFfiException() {
        override val message
            get() = "details=${ `details` }"
    }
    
    class InventoryException(
        
        val `details`: kotlin.String
        ) : ErpFfiException() {
        override val message
            get() = "details=${ `details` }"
    }
    
    class PluginException(
        
        val `details`: kotlin.String
        ) : ErpFfiException() {
        override val message
            get() = "details=${ `details` }"
    }
    
    class InvalidArgument(
        
        val `details`: kotlin.String
        ) : ErpFfiException() {
        override val message
            get() = "details=${ `details` }"
    }
    
    class NotFound(
        
        val `details`: kotlin.String
        ) : ErpFfiException() {
        override val message
            get() = "details=${ `details` }"
    }
    
    class InternalException(
        
        val `details`: kotlin.String
        ) : ErpFfiException() {
        override val message
            get() = "details=${ `details` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<ErpFfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): ErpFfiException = FfiConverterTypeErpFfiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeErpFfiError : FfiConverterRustBuffer<ErpFfiException> {
    override fun read(buf: ByteBuffer): ErpFfiException {
        

        return when(buf.getInt()) {
            1 -> ErpFfiException.DatabaseException(
                FfiConverterString.read(buf),
                )
            2 -> ErpFfiException.ModuleException(
                FfiConverterString.read(buf),
                )
            3 -> ErpFfiException.InventoryException(
                FfiConverterString.read(buf),
                )
            4 -> ErpFfiException.PluginException(
                FfiConverterString.read(buf),
                )
            5 -> ErpFfiException.InvalidArgument(
                FfiConverterString.read(buf),
                )
            6 -> ErpFfiException.NotFound(
                FfiConverterString.read(buf),
                )
            7 -> ErpFfiException.InternalException(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: ErpFfiException): ULong {
        return when(value) {
            is ErpFfiException.DatabaseException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`details`)
            )
            is ErpFfiException.ModuleException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`details`)
            )
            is ErpFfiException.InventoryException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`details`)
            )
            is ErpFfiException.PluginException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`details`)
            )
            is ErpFfiException.InvalidArgument -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`details`)
            )
            is ErpFfiException.NotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`details`)
            )
            is ErpFfiException.InternalException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`details`)
            )
        }
    }

    override fun write(value: ErpFfiException, buf: ByteBuffer) {
        when(value) {
            is ErpFfiException.DatabaseException -> {
                buf.putInt(1)
                FfiConverterString.write(value.`details`, buf)
                Unit
            }
            is ErpFfiException.ModuleException -> {
                buf.putInt(2)
                FfiConverterString.write(value.`details`, buf)
                Unit
            }
            is ErpFfiException.InventoryException -> {
                buf.putInt(3)
                FfiConverterString.write(value.`details`, buf)
                Unit
            }
            is ErpFfiException.PluginException -> {
                buf.putInt(4)
                FfiConverterString.write(value.`details`, buf)
                Unit
            }
            is ErpFfiException.InvalidArgument -> {
                buf.putInt(5)
                FfiConverterString.write(value.`details`, buf)
                Unit
            }
            is ErpFfiException.NotFound -> {
                buf.putInt(6)
                FfiConverterString.write(value.`details`, buf)
                Unit
            }
            is ErpFfiException.InternalException -> {
                buf.putInt(7)
                FfiConverterString.write(value.`details`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




